#!/usr/bin/env node
/**
 * Landing v2 — generate components/marketing/v2/icons.tsx from Phosphor duotone SVGs (MIT).
 *
 *   node scripts/marketing/build-icons.mjs
 *
 * Source: @phosphor-icons/core installed under promo-video/tools (git-ignored, local only).
 * The generated file is committed. The duotone layer is coloured brand blue at render time.
 */
import fs from "node:fs";
import path from "node:path";

const ROOT = path.resolve(path.dirname(new URL(import.meta.url).pathname), "../..");
const SRC = path.join(ROOT, "promo-video/tools/node_modules/@phosphor-icons/core/assets/duotone");
const NAMES = [
  // phase 1–3 (the promo video's set)
  "buildings", "calendar-check", "calendar-x", "chart-line-down", "chats-circle", "check", "coins", "door-open",
  "file-xls", "globe", "hand-coins", "notebook", "receipt", "seal-check", "tag", "vault", "wallet", "whatsapp-logo",
  // phase 4
  "device-mobile", "translate", "headset", "user-plus", "map-pin", "chat-circle-text",
];

const camel = (n) => n.split("-").map((w, i) => (i ? w[0].toUpperCase() + w.slice(1) : w)).join("");
const rows = NAMES.map((n) => {
  const raw = fs.readFileSync(path.join(SRC, `${n}-duotone.svg`), "utf8");
  const paths = [...raw.matchAll(/<path d="([^"]+)"( opacity="0.2")?\/>/g)];
  const duo = paths.filter((p) => p[2]).map((p) => p[1]).join(" ");
  const line = paths.filter((p) => !p[2]).map((p) => p[1]).join(" ");
  if (!line) throw new Error(`no line path in ${n}`);
  return `  ${camel(n)}: { duo: ${JSON.stringify(duo)}, line: ${JSON.stringify(line)} },`;
});

const tsx = `/* GENERATED by scripts/marketing/build-icons.mjs — do not edit by hand.
 * Phosphor duotone icons (MIT, phosphoricons.com) — the promo video's set plus a few for the landing page.
 * The duotone layer is brand blue, never gold. */

const ICONS = {
${rows.join("\n")}
} as const;

export type IconName = keyof typeof ICONS;

export function DuoIcon({
  name,
  size = 24,
  className = "",
  duo = "#185FA5",
  duoOpacity = 0.85,
  title,
}: {
  name: IconName;
  size?: number;
  className?: string;
  /** colour of the duotone layer (brand blue by default) */
  duo?: string;
  duoOpacity?: number;
  title?: string;
}) {
  const icon = ICONS[name];
  return (
    <svg
      viewBox="0 0 256 256"
      width={size}
      height={size}
      className={className}
      fill="currentColor"
      role={title ? "img" : undefined}
      aria-hidden={title ? undefined : true}
      aria-label={title}
    >
      {icon.duo && <path d={icon.duo} fill={duo} opacity={duoOpacity} />}
      <path d={icon.line} />
    </svg>
  );
}
`;
fs.writeFileSync(path.join(ROOT, "components/marketing/v2/icons.tsx"), tsx);
console.log(`wrote icons.tsx (${NAMES.length} icons)`);
